import {project,unproject} from './engine.js';
export function exampleData(){const sw=project([-73.9819,40.7681]),nw=project([-73.9582,40.8005]),se=project([-73.973,40.7644]);const L=Math.hypot(nw[0]-sw[0],nw[1]-sw[1]),W=Math.hypot(se[0]-sw[0],se[1]-sw[1]),v=[(nw[0]-sw[0])/L,(nw[1]-sw[1])/L],u=[(se[0]-sw[0])/W,(se[1]-sw[1])/W];const point=(x,y)=>[sw[0]+u[0]*x+v[0]*y,sw[1]+u[1]*x+v[1]*y];const ring=[[0,0],[W,0],[W,L],[0,L],[0,0]].map(([x,y])=>unproject(point(x,y)));const elements=[],ids=new Map();let id=1,way=100000;
 const node=(x,y,signal=false)=>{const p=point(x,y),key=x.toFixed(3)+':'+y.toFixed(3);if(ids.has(key))return ids.get(key);const n=id++,ll=unproject(p);elements.push({type:'node',id:n,lon:ll[0],lat:ll[1],tags:signal?{highway:'traffic_signals'}:{}});ids.set(key,n);return n;};
 const line=(a,b,name,oneway=false)=>{const count=Math.ceil(Math.hypot(a[0]-b[0],a[1]-b[1])/35),nodes=[];for(let i=0;i<=count;i++)nodes.push(node(a[0]+(b[0]-a[0])*i/count,a[1]+(b[1]-a[1])*i/count,i===count));elements.push({type:'way',id:way++,nodes,tags:{highway:'residential',name,horse:'designated',...(oneway?{oneway:'yes'}:{})}});};const xs=[-600,-300,-35,W+35,W+300,W+600],ys=[-600,-300,-35,...Array.from({length:8},(_,i)=>350+i*(L-700)/7),L+35,L+300,L+600];for(const x of xs)for(let j=1;j<ys.length;j++)line([x,ys[j-1]],[x,ys[j]],'Example north–south road');for(const y of ys)for(let j=1;j<xs.length;j++){const a=xs[j-1],b=xs[j];if(y>0&&y<L&&a<0&&b>W)continue;line([a,y],[b,y],'Example east–west road');}
 const corners=[[100,100],[W-100,100],[W-100,L-100],[100,L-100],[100,100]];for(let i=1;i<corners.length;i++)line(corners[i-1],corners[i],i===1?'Center Drive':i===2?'East Drive':'West Drive',true);
 line([-35,ys[5]],[W+35,ys[5]],'Example horse-only crossing');elements.at(-1).tags={highway:'bridleway',horse:'designated',foot:'no',bicycle:'no',name:'Example horse-only crossing'};
 const positions=[[-35,350],[-35,ys[5]],[-35,ys[8]],[W+35,350],[W+35,ys[5]],[W+35,ys[8]],[-300,-35],[W+300,L+35]];const stations=positions.map(([x,y],i)=>{const ll=unproject(point(x,y));return {id:'example-'+i,name:'Example station '+String(i+1).padStart(2,'0'),p:point(x,y),lon:ll[0],lat:ll[1],installed:true,renting:true,returning:true,ebikes:i===2?0:5+i,docks:i===3?0:8+i,timestamp:Date.now()/1000,battery:'unknown'};});return {geometry:{type:'Polygon',coordinates:[ring]},raw:{elements},stations,a:positions[0].map((_,i)=>point(...positions[0])[i]),b:point(...positions[5]),origin:'synthetic-example-not-navigation'};}
